use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use serde::Serialize;
use std::collections::BTreeMap;

pub struct InvoiceMonthlyCommand;

fn monthly_billable_seconds(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    entries
        .iter()
        .filter(|entry| entry.billable && !entry.is_running())
        .fold(BTreeMap::new(), |mut months, entry| {
            *months
                .entry(entry.start.format("%Y-%m").to_string())
                .or_default() += entry.duration;
            months
        })
}

#[derive(Serialize)]
struct InvoiceMonthlyJson {
    months: Vec<InvoiceMonthlyMonth>,
    total_billable_seconds: i64,
}

#[derive(Serialize)]
struct InvoiceMonthlyMonth {
    month: String,
    billable_seconds: i64,
}

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let months = monthly_billable_seconds(&entries);
        let total: i64 = months.values().sum();

        if json {
            let output = InvoiceMonthlyJson {
                months: months
                    .into_iter()
                    .map(|(month, billable_seconds)| InvoiceMonthlyMonth {
                        month,
                        billable_seconds,
                    })
                    .collect(),
                total_billable_seconds: total,
            };
            println!(
                "{}",
                serde_json::to_string(&output).expect("failed to serialize invoice to JSON")
            );
        } else if months.is_empty() {
            println!("(no data)");
        } else {
            for (month, seconds) in months {
                println!("{month}  {seconds}s");
            }
            println!("Total  {total}s");
        }
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::{monthly_billable_seconds, InvoiceMonthlyJson};
    use crate::models::TimeEntry;
    use chrono::DateTime;
    use chrono::Utc;

    fn entry(start: &str, duration: i64, billable: bool, stop: bool) -> TimeEntry {
        TimeEntry {
            id: 1,
            description: String::new(),
            start: start.parse::<DateTime<Utc>>().unwrap(),
            stop: stop.then_some(Utc::now()),
            duration,
            billable,
            workspace_id: 1,
            tags: vec![],
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn groups_stopped_billable_entries_by_utc_month() {
        let result = monthly_billable_seconds(&[
            entry("2026-02-28T23:59:00Z", 30, true, true),
            entry("2026-01-31T23:59:00Z", 10, true, true),
            entry("2026-02-01T00:00:00Z", 20, true, true),
        ]);

        assert_eq!(result.get("2026-01"), Some(&10));
        assert_eq!(result.get("2026-02"), Some(&50));
    }

    #[test]
    fn excludes_non_billable_and_running_entries() {
        let result = monthly_billable_seconds(&[
            entry("2026-01-01T00:00:00Z", 10, false, true),
            entry("2026-01-02T00:00:00Z", -1_767_000_000, true, false),
        ]);

        assert!(result.is_empty());
    }

    #[test]
    fn serializes_populated_json_in_month_order() {
        let months = monthly_billable_seconds(&[
            entry("2026-02-01T00:00:00Z", 20, true, true),
            entry("2026-01-01T00:00:00Z", 10, true, true),
        ]);
        let output = InvoiceMonthlyJson {
            months: months
                .into_iter()
                .map(|(month, billable_seconds)| super::InvoiceMonthlyMonth {
                    month,
                    billable_seconds,
                })
                .collect(),
            total_billable_seconds: 30,
        };

        assert_eq!(
            serde_json::to_string(&output).unwrap(),
            r#"{"months":[{"month":"2026-01","billable_seconds":10},{"month":"2026-02","billable_seconds":20}],"total_billable_seconds":30}"#
        );
    }

    #[test]
    fn serializes_empty_json() {
        let output = InvoiceMonthlyJson {
            months: vec![],
            total_billable_seconds: 0,
        };

        assert_eq!(
            serde_json::to_string(&output).unwrap(),
            r#"{"months":[],"total_billable_seconds":0}"#
        );
    }
}

